-- Reference grade: synthetic rows in a disposable fixture database.
-- Runs after reference-grade-setup.sql and 20261024225914 are installed over
-- the job-7 chain, so the accepted-roster epoch is noon UTC two days ago and
-- day D1 (yesterday) is wholly after it. Every mutation is rolled back by the
-- final ROLLBACK; helpers live in pg_temp. No production object, connection
-- or credential.
--
-- The hands between the $engine_hands$ markers are NOT hand-typed: each was
-- played through the real HandController and mapped to the persisted
-- hand_history.actions record exactly as ServerTableEngineHandEvents writes
-- it (forced posts, origin, isFullRaise and the captured public node).
-- server/src/services/horseCommitmentReferenceGrade.fixture.test.ts requires
-- this block to equal what the engine produces today. Each named check
-- counts once; the wrapper requires the exact total.
BEGIN;
SET LOCAL statement_timeout='60s';
CREATE TEMP TABLE checks(name text PRIMARY KEY);
GRANT SELECT,INSERT ON checks TO service_role,anon,authenticated;
CREATE FUNCTION pg_temp.ok(name text, cond boolean) RETURNS void LANGUAGE plpgsql AS $ok$
BEGIN
  IF cond IS DISTINCT FROM true THEN RAISE EXCEPTION 'reference_grade_check_failed: %', name; END IF;
  INSERT INTO checks VALUES(name);
END $ok$;
CREATE FUNCTION pg_temp.refused(stmt text, state text) RETURNS boolean LANGUAGE plpgsql AS $r$
DECLARE got_state text;
BEGIN
  BEGIN
    EXECUTE stmt;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS got_state=RETURNED_SQLSTATE;
    RETURN got_state=state;
  END;
  RETURN false;
END $r$;
CREATE FUNCTION pg_temp.hid(seed text) RETURNS uuid LANGUAGE sql AS $h$ SELECT md5('rg-'||seed)::uuid $h$;
