CREATE TEMP TABLE fx AS SELECT
  (transaction_timestamp() AT TIME ZONE 'UTC')::date-1 AS d1,
  '38383838-3838-4838-8838-383838383838'::uuid AS tbl,
  '39393939-3939-4939-8939-393939393939'::uuid AS mtt;
GRANT SELECT ON fx,engine_hands TO service_role,anon,authenticated;
INSERT INTO public.tournaments(id,tournament_type,table_size,max_players) SELECT mtt,'MTT',6,6 FROM fx;

-- The three push/fold charts these hands reach, in the live object format.
-- An absent hand is a fold. Cash|fold_to_hero|BTN|12 is deliberately absent.
INSERT INTO public.memory_charts_gold(chart_id,game_type,stack_depth,hero_position,villain_action,hand_matrix) VALUES
 ('t-btn-12','Tournament',12,'BTN','fold_to_hero',
  '{"AA":{"push":1,"fold":0},"A5s":{"push":0.964,"fold":0.036},"K9o":{"push":1,"fold":0},"J8o":{"push":0.41,"fold":0.59}}'),
 ('t-co-12','Tournament',12,'CO','fold_to_hero',
  '{"AA":{"push":1,"fold":0},"A5s":{"push":1,"fold":0},"K9o":{"push":0.88,"fold":0.12}}'),
 ('t-bb-13','Tournament',13,'BB','sb_push',
  '{"AA":{"call":1,"fold":0},"K9o":{"call":1,"fold":0},"T7o":{"call":0.05,"fold":0.95}}');

-- One accepted hand from an engine-produced record. Players: the dealt list.
-- The roster classifies the horse as a horse and every other seat human.
-- stats_facts carries hole cards for the horse only (opponents' mucked
-- holdings are irrelevant to its grade).
CREATE SEQUENCE pg_temp.hand_numbers START 3000001;
CREATE FUNCTION pg_temp.hand(seed text, at timestamptz, h jsonb, facts jsonb DEFAULT NULL)
RETURNS uuid LANGUAGE plpgsql AS $hand$
DECLARE f fx%ROWTYPE; id uuid:=pg_temp.hid(seed); n bigint:=nextval('pg_temp.hand_numbers');
  payload jsonb; payload_hash text; roster jsonb;
BEGIN
  SELECT * INTO f FROM fx;
  INSERT INTO public.hand_history(id,table_id,created_at,game_variant,big_blind,players,tournament_id,hand_number,actions)
    VALUES(id,f.tbl,at,h->>'variant',(h->>'bigBlind')::numeric,h->'players',
      CASE WHEN (h->>'tournament')::boolean THEN f.mtt END,n,h->'actions');
  payload:=jsonb_build_object('accepted_hand_facts',jsonb_build_object(
    'contributions',h->'contributions','returned_uncalled','{}'::jsonb,'insurance','[]'::jsonb,
    'stats_facts',coalesce(facts,jsonb_build_object('version',2,'transfers','[]'::jsonb,
      'facts',(SELECT jsonb_agg(jsonb_build_object('user_id',p->>'userId','seat',(p->>'seat')::int,
        'hole_cards',CASE WHEN p->>'userId'=h->>'horse' THEN h->'horseCards' END) ORDER BY (p->>'seat')::int)
        FROM jsonb_array_elements(h->'players') p)))));
  payload_hash:=encode(extensions.digest(convert_to(payload::text,'UTF8'),'sha256'),'hex');
  INSERT INTO public.hand_atomic_commits(hand_id,table_id,payload_hash,post_commit_payload_hash,post_commit_payload,
      hand_number,stack_result,committed_at,post_commit_request_hash,post_commit_completed_at)
    VALUES(id,f.tbl,repeat('a',64),payload_hash,payload,n,'{}'::jsonb,at,repeat('b',64),at);
  roster:=jsonb_build_object('version',1,'basis','profiles_read_in_acceptance_transaction',
    'tableId',f.tbl::text,'handId',id::text,'handNumber',n,
    'capturedAt',to_char(at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'actors',(SELECT jsonb_agg(jsonb_build_object('userId',p->>'userId','seat',(p->>'seat')::int,
      'seatId',md5(seed||(p->>'seat'))::uuid,'seatJoinedAt','2026-01-01T00:00:00Z',
      'classification',CASE WHEN p->>'userId'=h->>'horse' THEN 'horse' ELSE 'human' END,
      'status','canonical_boolean') ORDER BY (p->>'seat')::int) FROM jsonb_array_elements(h->'players') p));
  INSERT INTO smarter_private.accepted_hand_rosters(table_id,hand_number,hand_id,post_commit_payload_hash,status,roster,captured_at)
    VALUES(f.tbl,n,id,payload_hash,'captured',roster,at);
  RETURN id;
END $hand$;
-- The horse's own (non-forced) action records in a hand, for mutation.
CREATE FUNCTION pg_temp.mutate_horse(h jsonb, change jsonb, drop_key text DEFAULT NULL) RETURNS jsonb LANGUAGE sql AS $m$
  SELECT jsonb_set(h,'{actions}',(SELECT jsonb_agg(CASE WHEN a->>'userId'=h->>'horse' AND a->>'origin' IS DISTINCT FROM 'forced'
      THEN (a||change)-coalesce(drop_key,'') ELSE a END ORDER BY o) FROM jsonb_array_elements(h->'actions') WITH ORDINALITY x(a,o)))
$m$;
CREATE FUNCTION pg_temp.eh(name text) RETURNS jsonb LANGUAGE sql AS $e$ SELECT hand FROM engine_hands WHERE engine_hands.name=$1 $e$;
CREATE FUNCTION pg_temp.at(minutes integer) RETURNS timestamptz LANGUAGE sql AS
 $t$ SELECT (d1::timestamp AT TIME ZONE 'UTC')+interval '1 hour'+make_interval(mins=>minutes) FROM fx $t$;

SELECT pg_temp.ok('engine_hands_present',(SELECT count(*)=5 FROM engine_hands));
SELECT pg_temp.ok('grader_is_private',
  NOT EXISTS(SELECT 1 FROM unnest(ARRAY['anon','authenticated','service_role']) r
    CROSS JOIN unnest(ARRAY['public.fn_horse_commitment_reference_grade(jsonb,uuid,jsonb)',
      'public.fn_horse_commitment_reference_position(integer,integer,integer[])',
      'public.fn_horse_commitment_reference_hand_class(jsonb)']) f WHERE has_function_privilege(r,f,'EXECUTE')));
SELECT pg_temp.ok('hand_class_matches_gto_charts',
  public.fn_horse_commitment_reference_hand_class('[{"rank":"A","suit":"spades"},{"rank":"K","suit":"spades"}]')='AKs'
  AND public.fn_horse_commitment_reference_hand_class('[{"rank":"2","suit":"clubs"},{"rank":"7","suit":"hearts"}]')='72o'
  AND public.fn_horse_commitment_reference_hand_class('[{"rank":"T","suit":"clubs"},{"rank":"T","suit":"hearts"}]')='TT'
  AND public.fn_horse_commitment_reference_hand_class('[{"rank":"T","suit":"clubs"},{"rank":"T","suit":"clubs"}]') IS NULL
  AND public.fn_horse_commitment_reference_hand_class('[{"rank":"10","suit":"clubs"},{"rank":"T","suit":"hearts"}]') IS NULL
  AND public.fn_horse_commitment_reference_hand_class('[{"rank":"A","suit":"spades"}]') IS NULL
  AND public.fn_horse_commitment_reference_hand_class(NULL) IS NULL);
SELECT pg_temp.ok('position_matches_horse_logic',
  -- 6-max, button 4: SB 5, BB 6, UTG 1 early, 2 middle, CO 3 and BTN 4 late.
  ARRAY(SELECT public.fn_horse_commitment_reference_position(s,4,ARRAY[1,2,3,4,5,6]) FROM generate_series(1,6) s)
    =ARRAY['early','middle','late','late','sb','bb']
  -- 9-max, button 9: three early, two middle, two late.
  AND ARRAY(SELECT public.fn_horse_commitment_reference_position(s,9,ARRAY[1,2,3,4,5,6,7,8,9]) FROM generate_series(1,9) s)
    =ARRAY['sb','bb','early','early','early','middle','middle','late','late']
  -- Heads-up: the dealer posts the small blind.
  AND public.fn_horse_commitment_reference_position(3,3,ARRAY[3,7])='sb'
  AND public.fn_horse_commitment_reference_position(7,3,ARRAY[3,7])='bb'
  -- A dead button keeps its place; the next dealt seat is the small blind.
  AND public.fn_horse_commitment_reference_position(5,4,ARRAY[1,2,3,5,6])='sb');

SELECT pg_temp.hand('open-jam-agreed',pg_temp.at(1),pg_temp.eh('open_jam_agreed'));
SELECT pg_temp.hand('open-jam-deviation',pg_temp.at(2),pg_temp.eh('open_jam_deviation'));
SELECT pg_temp.hand('bb-defend-agreed',pg_temp.at(3),pg_temp.eh('bb_defend_agreed'));
SELECT pg_temp.hand('deep-cash',pg_temp.at(4),pg_temp.eh('deep_cash_out_of_domain'));
SELECT pg_temp.hand('plo4',pg_temp.at(5),pg_temp.eh('plo4_out_of_domain'));
-- Genuinely unmatched or ungradable variants of the agreed hand.
SELECT pg_temp.hand('no-hole-cards',pg_temp.at(6),pg_temp.eh('open_jam_agreed'),
  '{"version":2,"facts":[],"transfers":[]}'::jsonb);
SELECT pg_temp.hand('node-missing',pg_temp.at(7),pg_temp.mutate_horse(pg_temp.eh('open_jam_agreed'),'{}','publicNode'));
SELECT pg_temp.hand('origin-missing',pg_temp.at(8),pg_temp.mutate_horse(pg_temp.eh('open_jam_agreed'),'{}','origin'));
SELECT pg_temp.hand('fallback',pg_temp.at(9),pg_temp.mutate_horse(pg_temp.eh('open_jam_agreed'),'{"origin":"horse_fallback"}'));
SELECT pg_temp.hand('cash-chart-missing',pg_temp.at(10),(SELECT jsonb_set(h,'{actions}',(SELECT jsonb_agg(CASE WHEN a ? 'publicNode'
    THEN jsonb_set(a,'{publicNode,mode}','"cash"') ELSE a END ORDER BY o) FROM jsonb_array_elements(h->'actions') WITH ORDINALITY x(a,o)))
  FROM (SELECT pg_temp.eh('open_jam_agreed') h) s));
SELECT pg_temp.hand('straddle',pg_temp.at(11),(SELECT jsonb_set(h,'{actions}',(h->'actions')||jsonb_build_array(jsonb_build_object(
    'seat',1,'userId','00000000-0000-4000-8000-000000000001','action','straddle','amount',200,'timestamp',0,
    'stage','preflop','origin','forced','dead',false))) FROM (SELECT pg_temp.eh('open_jam_agreed') h) s));
SELECT pg_temp.hand('unknown-commitment',pg_temp.at(12),(SELECT jsonb_set(h,ARRAY['contributions',h->>'horse'],'"1200"')
  FROM (SELECT pg_temp.eh('open_jam_agreed') h) s));
-- A row written before this body: its first-write content must survive.
SELECT pg_temp.hand('preexisting',pg_temp.at(13),pg_temp.eh('open_jam_agreed'));
INSERT INTO public.horse_commitment_reviews(hand_id,horse_user_id,table_id,played_at,source_payload_hash,game_variant,format,
  seats,big_blind,net_contribution,returned_uncalled,committed_amount,committed_bb,eligibility,reasons)
SELECT h.id,'00000000-0000-4000-8000-000000000004',h.table_id,h.created_at,c.post_commit_payload_hash,'nlh','mtt',6,100,1200,0,1200,12,
  'over_10bb',ARRAY['decision_replay_not_matched','reference_not_matched']
FROM public.hand_history h JOIN public.hand_atomic_commits c ON c.hand_id=h.id WHERE h.id=pg_temp.hid('preexisting');
CREATE TEMP TABLE preexisting_before AS SELECT * FROM public.horse_commitment_reviews;

-- Drive the step to idle as its only caller does.
CREATE TEMP TABLE step_results(n serial, r jsonb);
GRANT ALL ON step_results TO service_role; GRANT ALL ON SEQUENCE step_results_n_seq TO service_role;
SET LOCAL ROLE service_role;
INSERT INTO step_results(r) SELECT public.fn_horse_commitment_audit_step() FROM generate_series(1,6);
RESET ROLE;
SELECT pg_temp.ok('step_reaches_idle_with_unchanged_receipt',
  (SELECT r->>'status' FROM step_results ORDER BY n DESC LIMIT 1)='idle'
  AND NOT EXISTS(SELECT 1 FROM step_results WHERE r->>'status' IN ('recorded','pass_complete')
    AND (r->>'gtoVerdict' IS DISTINCT FROM 'unverified' OR r->>'sourceCoverage' IS DISTINCT FROM 'not_established'
      OR r->'activationAuthorized' IS DISTINCT FROM 'false'::jsonb)));
CREATE FUNCTION pg_temp.review(seed text) RETURNS public.horse_commitment_reviews LANGUAGE sql AS
 $v$ SELECT * FROM public.horse_commitment_reviews WHERE hand_id=pg_temp.hid(seed) $v$;
SELECT pg_temp.ok('only_the_horse_is_reviewed',
  (SELECT count(*)=13 AND count(DISTINCT hand_id)=13 FROM public.horse_commitment_reviews)
  AND NOT EXISTS(SELECT 1 FROM public.horse_commitment_reviews r JOIN engine_hands e ON true
    WHERE r.hand_id=pg_temp.hid('open-jam-agreed') AND r.horse_user_id::text<>(SELECT hand->>'horse' FROM engine_hands WHERE name='open_jam_agreed')));
SELECT pg_temp.ok('open_jam_graded_agreed',
  (SELECT gto_verdict='reference_agreed' AND eligibility='over_10bb' AND committed_bb=12 AND format='mtt'
     AND reasons=ARRAY['reference_agreed:open_jam:Tournament|fold_to_hero|BTN|12:A5s:push:0.964']
   FROM pg_temp.review('open-jam-agreed')));
SELECT pg_temp.ok('open_jam_graded_deviation',
  (SELECT gto_verdict='reference_deviation'
     AND reasons=ARRAY['reference_deviation:open_jam:Tournament|fold_to_hero|CO|12:72o:push:0.000']
   FROM pg_temp.review('open-jam-deviation')));
SELECT pg_temp.ok('bb_defend_graded_agreed',
  (SELECT gto_verdict='reference_agreed' AND committed_bb=13
     AND reasons=ARRAY['reference_agreed:bb_defend:Tournament|sb_push|BB|13:K9o:call:1.000']
   FROM pg_temp.review('bb-defend-agreed')));
SELECT pg_temp.ok('deep_cash_names_each_ungraded_decision',
  (SELECT gto_verdict='unverified' AND format='cash'
     AND reasons=ARRAY['reference_domain_depth:open_jam','reference_domain_spot:facing_raise']
   FROM pg_temp.review('deep-cash')));
SELECT pg_temp.ok('plo_names_its_variant',
  (SELECT gto_verdict='unverified' AND game_variant='plo4' AND reasons=ARRAY['reference_domain_variant:plo4']
   FROM pg_temp.review('plo4')));
SELECT pg_temp.ok('missing_hole_cards_named',
  (SELECT gto_verdict='unverified' AND reasons=ARRAY['decision_hole_cards_unavailable'] FROM pg_temp.review('no-hole-cards')));
SELECT pg_temp.ok('missing_public_node_named',
  (SELECT gto_verdict='unverified' AND reasons=ARRAY['decision_public_node_unavailable'] FROM pg_temp.review('node-missing')));
SELECT pg_temp.ok('missing_origin_named',
  (SELECT gto_verdict='unverified' AND reasons=ARRAY['decision_origin_unavailable'] FROM pg_temp.review('origin-missing')));
SELECT pg_temp.ok('fallback_never_graded',
  (SELECT gto_verdict='unverified' AND reasons=ARRAY['decision_fallback_not_graded'] FROM pg_temp.review('fallback')));
SELECT pg_temp.ok('missing_chart_named',
  (SELECT gto_verdict='unverified' AND reasons=ARRAY['reference_chart_unavailable:Cash|fold_to_hero|BTN|12']
   FROM pg_temp.review('cash-chart-missing')));
SELECT pg_temp.ok('straddle_out_of_domain',
  (SELECT gto_verdict='unverified' AND reasons=ARRAY['reference_domain_straddle'] FROM pg_temp.review('straddle')));
SELECT pg_temp.ok('unknown_commitment_not_graded',
  (SELECT gto_verdict='unverified' AND eligibility='unknown'
     AND reasons=ARRAY['commitment_eligibility_unknown','reference_not_graded_commitment_unknown']
   FROM pg_temp.review('unknown-commitment')));
SELECT pg_temp.ok('first_write_preserved',
  NOT EXISTS((SELECT r.* FROM public.horse_commitment_reviews r JOIN preexisting_before o USING(hand_id,horse_user_id)
    EXCEPT SELECT * FROM preexisting_before)
   UNION ALL (SELECT * FROM preexisting_before EXCEPT
    SELECT r.* FROM public.horse_commitment_reviews r JOIN preexisting_before o USING(hand_id,horse_user_id))));
SELECT pg_temp.ok('no_placeholder_on_new_rows',
  NOT EXISTS(SELECT 1 FROM public.horse_commitment_reviews WHERE hand_id<>pg_temp.hid('preexisting')
    AND reasons && ARRAY['decision_replay_not_matched','reference_not_matched']));
SELECT pg_temp.ok('every_unverified_row_says_why',
  NOT EXISTS(SELECT 1 FROM public.horse_commitment_reviews WHERE gto_verdict='unverified' AND cardinality(reasons)=0));
SELECT pg_temp.ok('grader_direct_edges',
  public.fn_horse_commitment_reference_grade('{}'::jsonb,gen_random_uuid(),NULL)
    ='{"verdict":"unverified","reasons":["decision_actions_unavailable"]}'::jsonb
  AND public.fn_horse_commitment_reference_grade((SELECT hand->'actions' FROM engine_hands WHERE name='open_jam_agreed'),
    gen_random_uuid(),NULL)='{"verdict":"unverified","reasons":["decision_not_found"]}'::jsonb
  -- A malformed public node is named, never raised through the step.
  AND (public.fn_horse_commitment_reference_grade(
    (SELECT pg_temp.mutate_horse(hand,'{"publicNode":{"status":"captured","variant":"nlh","street":"preflop","structure":"no_limit","bigBlind":"x"}}')->'actions'
       FROM engine_hands WHERE name='open_jam_agreed'),
    '00000000-0000-4000-8000-000000000004',
    '{"facts":[{"user_id":"00000000-0000-4000-8000-000000000004","hole_cards":[{"rank":"A","suit":"spades"},{"rank":"5","suit":"spades"}]}]}')
    ->'reasons'->>0) LIKE 'reference_grade_unreadable:%');
SELECT pg_temp.ok('verdict_column_refuses_invented_values',
  pg_temp.refused($s$UPDATE public.horse_commitment_reviews SET gto_verdict='correct' WHERE hand_id=md5('rg-plo4')::uuid$s$,'23514')
  AND pg_temp.refused($s$UPDATE public.horse_commitment_reviews SET gto_verdict='reference_agreed'
    WHERE hand_id=md5('rg-unknown-commitment')::uuid$s$,'23514'));
-- The private reader serves the graded reasons unchanged to the daily review.
CREATE TEMP TABLE page(v jsonb); GRANT ALL ON page TO service_role;
SET LOCAL ROLE service_role;
SELECT set_config('request.jwt.claim.role','service_role',true);
INSERT INTO page SELECT public.fn_horse_commitment_review_page((SELECT d1 FROM fx));
RESET ROLE;
SELECT pg_temp.ok('reader_serves_graded_reasons',
  (SELECT jsonb_array_length(v->'rows')=8 AND (v->>'hasMore')::boolean AND v->>'identityBasis'='accepted_roster'
     AND (SELECT r->'reasons'='["reference_agreed:open_jam:Tournament|fold_to_hero|BTN|12:A5s:push:0.964"]'::jsonb
            AND r->>'status'='retained_diagnostic' AND r->>'eligibility'='over_10bb'
          FROM jsonb_array_elements(v->'rows') r WHERE r->>'handId'=pg_temp.hid('open-jam-agreed')::text)
   FROM page));
SELECT 'synthetic_reference_grade_controls_only_if_executed',(SELECT count(*) FROM checks);
ROLLBACK;
